+  private normalizeCursorOrderBy(orderBy: any): {
+    field: string;
+    dir: 'asc' | 'desc';
+  }[] {
+    const values = Array.isArray(orderBy) ? orderBy : [orderBy];
+    const sort = values.flatMap((value) =>
